;; curriculum: Calc-2 (undergrad) — improper integrals; prerequisites: area, decay
;; math target: y = 1 + 12/(x+12) has an infinite tail but the area under it stays finite.

app riya-level-tail "1.1.0"
"riya level 17 · Tail — the tail runs on forever and never touches y = 1, yet the shaded area above y = 1 stays finite. Skate the tail and feel the area fill — catch 5 ★! Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas so the axes and the world's own function stay visible. Rebound into the riya-game-platformer organism (menu + all eighteen worlds)."

;; @exposure internal

orbital RiyaTailOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaTailBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaTailPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaTailFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaTailPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaTailCurveSample = {
    x : number!
    y : number!
  }
  type RiyaTailCurve = {
    label : string
    color : string
    samples : [RiyaTailCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaTailGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaTailFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  entity RiyaTailState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaTailBody = { x: -9, y: 6, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaTailPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaTailFx] = []
    celebrated : boolean = false
    platforms : [RiyaTailPlatform] = []
    curves : [RiyaTailCurve] = []
    guides : [RiyaTailGuide] = []
    areaSamples : [RiyaTailCurveSample] = []
    zoneId : string = "tail"
  }

  entity TailTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait TailBody = Body.traits.PlatformerBody -> RiyaTailState {
    events {
      STEER: TAIL_STEER
      JUMP: TAIL_LEAP
      PLACE: TAIL_PLACE
      RESTART: TAIL_RESTART
      SET_PLATFORMS: TAIL_SET_PLATFORMS
      SET_SKATE_CURVE: TAIL_SET_SKATE_CURVE
      BODY_MOVED: TAIL_MOVED
      BODY_JUMPED: TAIL_JUMPED
      BODY_LANDED: TAIL_LANDED
      BODY_HAZARD: TAIL_HAZARD
      BODY_GOAL: TAIL_GOAL
      BODY_FELL: TAIL_FELL
      BODY_SKATE_START: TAIL_SKATE_ON
      BODY_SKATE_END: TAIL_SKATE_OFF
    }
    config {
      running: true
      spawn: { x: -9, y: 6, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      skateSnap: 0.9
    }
  }

  trait TailGate = Gate.traits.ObjectiveFlow -> RiyaTailState {
    events {
      PROGRESS: TAIL_PROGRESS
      GAME_END: TAIL_GAME_END
      RESTART: TAIL_RESTART
    }
    config { running: true }
  }

  trait TailFx = Particles.traits.FxParticles -> RiyaTailState {
    events {
      BURST: TAIL_BURST
    }
    config { running: true }
  }

  trait TailTutorialPreview -> TailTutorialData [interaction, instance] {
    initial: idle
    state idle {
      INIT -> idle
        (render-ui center null)
    }
  }

  trait TailTutorial = Tutorial.traits.TutorialOverlay -> TailTutorialData {
    events {
      SHOW: TAIL_TUTORIAL_SHOW
      TUTORIAL_DONE: TAIL_TUTORIAL_DONE
    }
    config {
      autoShow: true
      previewTrait: @trait.TailTutorialPreview
      steps: [
        { id: "intro", title: "Tail", body: "The bars are the curve y = 1 + 12/(x+12). It creeps toward y = 1 but never touches it — yet the shaded area between them stays finite. Skate, collect ★, and grab the →1 pad." }
      ]
    }
  }

  trait TailPickup = Pickup.traits.Pickup -> RiyaTailState {
    events {
      PICKED: TAIL_PICKED
      COLLECT: TAIL_COLLECT
      PICKUP_SET_COMPLETED: TAIL_PICKUP_SET_COMPLETED
      SET_FEATURES: TAIL_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait TailLevelData -> @rebindable RiyaTailState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "tail"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn k @k))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          areaSamples: (array/map @config.areaSamples (fn a @a))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaTailPlatform]!
        stars : [RiyaTailPickup]!
        skateCurve : [RiyaTailCurveSample]
        curveOverlay : [RiyaTailCurve]
        guides : [RiyaTailGuide]
        areaSamples : [RiyaTailCurveSample]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "Tail"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "y = 1 + 12/(x+12)"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "the tail runs on forever and never touches y = 1 — yet the area between the curve and y = 1 stays finite"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#38bdf8"
        @label "Region Color"
        @description "Zone band accent in the open world."
        @tier "presentation"
      entryY : number = 4.7
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge; the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 1.6
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge; the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaTailPlatform] = [
        { id: "b0", x: -9.6, y: -2, width: 1.6, height: 6.7, type: "ground" }
        { id: "b1", x: -8, y: -2, width: 1.6, height: 5.5, type: "ground" }
        { id: "b2", x: -6.4, y: -2, width: 1.6, height: 4.9, type: "ground" }
        { id: "b3", x: -4.8, y: -2, width: 1.6, height: 4.5, type: "ground" }
        { id: "b4", x: -3.2, y: -2, width: 1.6, height: 4.3, type: "ground" }
        { id: "b5", x: -1.6, y: -2, width: 1.6, height: 4.1, type: "ground" }
        { id: "b6", x: 0, y: -2, width: 1.6, height: 3.9, type: "ground" }
        { id: "b7", x: 1.6, y: -2, width: 1.6, height: 3.8, type: "ground" }
        { id: "b8", x: 3.2, y: -2, width: 1.6, height: 3.8, type: "ground" }
        { id: "b9", x: 4.8, y: -2, width: 1.6, height: 3.7, type: "ground" }
        { id: "b10", x: 6.4, y: -2, width: 1.6, height: 3.6, type: "ground" }
        { id: "b11", x: 8, y: -2, width: 1.6, height: 3.6, type: "ground" }
      ]
