  trait RiyaTailGenre = Genre.traits.PlatformerPuzzle -> RiyaTailState {
    config {
      agencyTrait: @trait.TailBody
      challengeTrait: @trait.TailBody
      goalTrait: @trait.TailGate
      rewardTrait: @trait.TailPickup
      feedbackTrait: @trait.TailFx
    }
  }

  trait RiyaTailPlay -> @rebindable RiyaTailState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit TAIL_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            guides: @entity.guides
            keyMap: { ArrowLeft: "TAIL_LEFT", KeyA: "TAIL_LEFT", ArrowRight: "TAIL_RIGHT", KeyD: "TAIL_RIGHT", ArrowUp: "TAIL_JUMP", KeyW: "TAIL_JUMP", Space: "TAIL_JUMP" }
            keyUpMap: { ArrowLeft: "TAIL_STOP", KeyA: "TAIL_STOP", ArrowRight: "TAIL_STOP", KeyD: "TAIL_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            regions: [ { samples: (array/filter @entity.areaSamples (fn smp (<= (object/get @smp x) (+ @entity.body.x 0.3)))), baseline: 1, color: @config.regionColor, opacity: 0.25, label: "∫ so far" } ]
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "TAIL_LEFT", right: "TAIL_RIGHT", up: "TAIL_JUMP" }, directionReleaseEvents: { left: "TAIL_STOP", right: "TAIL_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "tail")
        (set @entity.curves @payload.curveOverlay)
        (set @entity.guides @payload.guides)
        (set @entity.areaSamples @payload.areaSamples)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit TAIL_SET_PLATFORMS { platforms: @payload.platforms })
        (emit TAIL_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit TAIL_SET_FEATURES { features: @payload.stars })

      TAIL_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit TAIL_STEER { dir: -1 })

      TAIL_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit TAIL_STEER { dir: 1 })

      TAIL_STOP -> idle when (== @entity.active true)
        (emit TAIL_STEER { dir: 0 })

      TAIL_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit TAIL_LEAP {})

      TAIL_FELL -> idle when (== @entity.active true)
        (emit TAIL_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit TAIL_BURST { particles: (array/map [ "fx-tail-fell" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "💫", ttl: 3 })) })

      TAIL_SKATE_ON -> idle when (== @entity.active true)
        (emit TAIL_BURST { particles: (array/concat
          { id: "narrative-skate", type: "narrative", x: @entity.body.x, z: (+ @entity.body.y 2), y: 0, message: "the area stops growing", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
          {
            id: "fx-tail-skate",
            type: "info",
            x: @payload.x,
            z: (+ @payload.y 0.6),
            y: 0,
            message: (str/concat @config.equationText " · x = " (math/round (+ @payload.x 0.3) 1)),
            ttl: 4
          }
        ) })
      TAIL_PICKED -> idle when (== @entity.active true)
        (emit TAIL_BURST { particles: (array/map [ "fx-pickup-" ] (fn fid { id: (str/concat @fid @payload.id), type: "pickup", x: @payload.x, z: @payload.y, message: @payload.glyph, ttl: 2 })) })
      TAIL_COLLECT -> idle when (== @entity.active true)
        (set @entity.score @payload.total)
        (set @entity.objectivesLeft (- (array/len @entity.pickups) @payload.total))
        (emit TAIL_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })

      TAIL_PICKUP_SET_COMPLETED -> idle when (== @entity.active true)
        (emit TAIL_BURST { particles: (array/map [ "complete" ] (fn _ { id: "narrative-complete", type: "narrative", x: 0, z: 8, y: 0, message: "finite area under an infinite tail", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
        (emit TAIL_PROGRESS { objectivesLeft: 0, movesLeft: 9999 })
      TAIL_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "tail" })

      TAIL_TUTORIAL_DONE -> idle
        (emit TAIL_BURST { particles: (array/map [ "tutorial" ] (fn _ { id: "narrative-tutorial", type: "narrative", x: 0, z: 10, y: 0, message: "the tail never touches y = 1", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
    }

    ticks {
      renderTick every 100ms when (== @entity.active true)
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            guides: @entity.guides
            keyMap: { ArrowLeft: "TAIL_LEFT", KeyA: "TAIL_LEFT", ArrowRight: "TAIL_RIGHT", KeyD: "TAIL_RIGHT", ArrowUp: "TAIL_JUMP", KeyW: "TAIL_JUMP", Space: "TAIL_JUMP" }
            keyUpMap: { ArrowLeft: "TAIL_STOP", KeyA: "TAIL_STOP", ArrowRight: "TAIL_STOP", KeyD: "TAIL_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            regions: [ { samples: (array/filter @entity.areaSamples (fn smp (<= (object/get @smp x) (+ @entity.body.x 0.3)))), baseline: 1, color: @config.regionColor, opacity: 0.25, label: "∫ so far" } ]
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
    }

    emits {
      TAIL_LEFT -> external {
        id : string
      }
        @description "Run-left intent from ArrowLeft/KeyA keydown or d-pad (forwarded as STEER dir −1)."
        @tier "domain"
      TAIL_RIGHT -> external {
        id : string
      }
        @description "Run-right intent from ArrowRight/KeyD keydown or d-pad (forwarded as STEER dir +1)."
        @tier "domain"
      TAIL_STOP -> external {
        id : string
      }
        @description "Left/right key release (keyUpMap or d-pad release); forwarded as STEER dir 0."
        @tier "domain"
      TAIL_JUMP -> external {
        id : string
      }
        @description "Jump intent from Space/ArrowUp/KeyW or d-pad up; forwarded as the body authority's renamed JUMP (TAIL_LEAP), which accepts it only while grounded."
        @tier "domain"
      TAIL_STEER -> external {
        dir : number!
      }
        @description "Renamed STEER consumed by this world's platformer-body authority (−1/0/+1 × moveSpeed)."
        @tier "domain"
      TAIL_LEAP -> external {
        id : string
      }
        @description "Renamed JUMP consumed by this world's platformer-body authority (grounded-gated vertical kick)."
        @tier "domain"
      TAIL_PLACE -> external {
        x : number!
        y : number!
      }
        @description "Renamed PLACE consumed by this world's platformer-body authority; the pit-fall respawn teleport."
        @tier "domain"
      TAIL_FELL -> external {
        x : number!
        y : number!
      }
        @description "Pit-fall signal from this world's platformer-body authority (renamed BODY_FELL); respawns riya at her spawn with every star kept."
        @tier "domain"
      TAIL_SKATE_ON -> external {
        x : number!
        y : number!
        slope : number!
      }
        @description "Skate-engage signal from this world's platformer-body authority (renamed BODY_SKATE_START); riya touched the tail curve — fires the equation fx burst."
        @tier "domain"
      TAIL_PICKED -> external {
        id : string!
        kind : string!
        x : number!
        y : number!
        glyph : string
        message : string
      }
        @description "A pickup was collected (renamed PICKED from std-pickup); the play trait bursts the glyph, the challenge trait applies id-conditional effects."
        @tier "domain"
      TAIL_COLLECT -> external {
        total : number!
      }
        @description "Running pickup count (renamed COLLECT from std-pickup); updates score/objectives and forwards to the objective-flow gate."
        @tier "domain"
      TAIL_PICKUP_SET_COMPLETED -> external {
      }
        @description "Every pickup in the set is collected (renamed PICKUP_SET_COMPLETED from std-pickup)."
        @tier "domain"
      TAIL_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's platformer-body/objective-flow/pickup authorities (renamed RESTART)."
        @tier "domain"
      TAIL_BURST -> external {
        particles : [RiyaTailFx]
      }
        @description "Particle batch spawned on star pickup, boost pickup or pit respawn; fx-particles fades it."
        @tier "domain"
      TAIL_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted by the Play trait; the objective-flow gate resolves won from it."
        @tier "domain"
      TAIL_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won clears the level."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
      TAIL_SET_PLATFORMS -> external {
        platforms : [RiyaTailPlatform]!
      }
        @description "Renamed SET_PLATFORMS consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA terrain to collision."
        @tier "domain"
      TAIL_SET_SKATE_CURVE -> external {
        curve : [RiyaTailCurveSample]!
      }
        @description "Renamed SET_SKATE_CURVE consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA skate rail."
        @tier "domain"
      TAIL_SET_FEATURES -> external {
        features : [RiyaTailPickup]!
      }
        @description "Renamed SET_FEATURES consumed by this world's pickup authority; forwards the canonical RIYA_LEVEL_DATA stars."
        @tier "domain"
    }

    listens {
      TAIL_TUTORIAL_DONE { id : string }
      RIYA_LEVEL_DATA {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaTailPlatform]!
        stars : [RiyaTailPickup]!
        skateCurve : [RiyaTailCurveSample]
        curveOverlay : [RiyaTailCurve]
        guides : [RiyaTailGuide]
        areaSamples : [RiyaTailCurveSample]
      }
    }

    config {
      equationText : string = "y = 1 + 12/(x+12)"
        @label "Equation Text"
        @description "Equation of this world's curve, shown by the skate fx burst."
        @tier "presentation"
      equationColor : string = "#7dd3fc"
        @label "Equation Color"
        @description "Color of the floating equation label that follows riya while she skates."
        @tier "presentation"
      curveSkateColor : string = "#f0abfc"
        @label "Curve Skate Color"
        @description "Curve trace color while riya is skating the graph."
        @tier "presentation"
      regionColor : string = "#38bdf8"
        @label "Region Color"
        @description "Fill color of the accumulating area region between the tail and y = 1."
        @tier "presentation"
      respawnX : number = -9
        @label "Respawn X"
        @description "X riya teleports to after a pit fall (matches TailBody spawn.x)."
        @tier "domain"
      respawnY : number = 6
        @label "Respawn Y"
        @description "Y riya teleports to after a pit fall (matches TailBody spawn.y)."
        @tier "domain"
      reachRadius : number = 0.7
        @label "Reach Radius"
        @description "Legacy reach distance; std-pickup uses its own reachX/reachY."
        @tier "domain"
      objectiveText : string = ""
        @label "Objective Text"
        @description "HUD objective text — intentionally empty; the curve, region fill and guide carry the objective."
        @tier "presentation"
      worldName : string = "Tail"
        @label "World Name"
        @description "This world's display name, shown in the game-shell title chip as \"riya · <worldName>\"."
        @tier "presentation"
      showTelemetry : boolean = false
        @label "Show Telemetry"
        @description "When true, draws a compact x/y/v readout on the canvas near riya (debug aid only). Off keeps the HUD to score only."
        @tier "domain"
      arrowOffsetY : number = 1.9
        @label "Arrow Offset Y"
        @description "World units above the body center where the velocity vector arrow originates, so it floats above the player sprite."
        @tier "presentation"
      arrowScale : number = 0.5
        @label "Arrow Scale"
        @description "Scale factor for the velocity vector arrow, kept short so it does not dip behind the sprite."
        @tier "presentation"
      fxPresets : [RiyaTailFxPreset] = [ { type: "info", color: "#38bdf8", color2: "#0c4a6e", size: 0.8, shape: "puff", count: 4 }, { type: "pickup", color: "#ffe066", color2: "#ffffff", size: 1.0, shape: "spark", count: 5, glow: 0.12, vy: -0.1 }, { type: "narrative", color: "#38bdf8", size: 1.4, shape: "ring", count: 1, glow: 0.1 } ]
        @label "Fx Presets"
        @description "Look table for world-space particle effects rendered by the draw-fx-layer."
        @tier "presentation"
      conceptText : string = "the tail runs on forever and never touches y = 1 — yet the area between the curve and y = 1 stays finite"
