        @tier "presentation"
      yMax : number = 12
        @label "Y Max"
        @description "Top edge of the visible math window."
        @tier "presentation"
      width : number = 800
        @label "Canvas Width"
        @description "math-canvas display width in px."
        @tier "presentation"
      height : number = 480
        @label "Canvas Height"
        @description "math-canvas display height in px."
        @tier "presentation"
    }
  }

  trait TailChallenge -> @rebindable RiyaTailState [game-core, instance] {
    initial: idle

    state idle {
      TAIL_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (str/endsWith @payload.id "tune-1")
          (emit TAIL_BURST { particles: [ { id: "narrative-tune", type: "narrative", x: @payload.x, z: (+ @payload.y 2), y: 0, message: "y → 1", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 } ] })
          null)
    }

    emits {
      TAIL_BURST -> external {
        particles : [RiyaTailFx]
      }
        @description "Particle batch spawned on the asymptote-pad narrative beat; fx-particles fades it."
        @tier "domain"
    }

    listens {
      TAIL_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "tail"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaTailClear -> @rebindable RiyaTailState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "TAIL_NEXT", variant: "primary" } ]
        })

      TAIL_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      TAIL_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-tail"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Tail clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "The tail never arrives at y = 1, but its area does not blow up — convergence."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-tail" as RiyaTailPage -> TailLevelData, TailBody, TailGate, TailFx, TailPickup, TailTutorial, RiyaTailGenre, RiyaTailPlay, TailChallenge, RiyaTailClear
}
